_TAP_NOT_OK_RE = re.compile(r"^not ok\s+\d+\s*(?:-\s*)?(.+)$")
_BATS_PRETTY_FAIL_RE = re.compile(r"^\s*\d+/\d+\s+[✗✖]\s+(.+)$")
_TAP_SUMMARY_COMMENT_RE = re.compile(
    r"^(?:Subtest:|tests\s+\d+|suites\s+\d+|pass\s+\d+|fail\s+\d+|cancelled\s+\d+|skipped\s+\d+|todo\s+\d+|duration_ms\s+[\d.]+)\b"
