def _parse_tap_yaml_block(yaml_lines: list[str], ctx: _TaskContext) -> tuple[str, list[str], str | None, list[str]]:
    """Parse TAP v13 YAML diagnostic block (e.g. `node --test` piped output)."""
    returned: list[str] = []
    diff_student: list[str] = []
    actual_yaml: list[str] = []
    frames: list[str] = []
    err_name = ""
    err_first = ""
    section = ""
    in_diff = False

    for ln in yaml_lines:
        s = ln.strip()
        if not s:
            continue
        top = re.match(r"^  ([A-Za-z_][A-Za-z0-9_]*):\s*(.*)$", ln)
        if top:
            section, val = top.group(1), top.group(2).strip()
            in_diff = False
            if section == "name":
                err_name = val.strip("'\"")
            elif section == "expected" and val and val != "|-":
                ctx.add_private_text(val)
            elif section == "actual" and val and val != "|-":
                actual_yaml.append(val)
            elif section == "error" and val and val != "|-":
                err_first = val.strip("'\"")
            continue

        if section == "error":
            if s == "+ actual - expected":
                in_diff = True
                continue
            if in_diff:
                stripped4 = ln[4:] if ln.startswith("    ") else ln
                if stripped4.startswith("-"):
                    ctx.add_private_text(stripped4[1:].strip())
                elif stripped4.startswith("+"):
                    diff_student.append(stripped4[1:].lstrip())
                else:
                    diff_student.append(stripped4)
            elif not err_first and not s.startswith("Expected values"):
                err_first = s
        elif section == "expected":
            ctx.add_private_text(s)
        elif section == "actual":
            actual_yaml.append(s)
        elif section == "stack":
            m_loc = re.search(r"\(?((?:file://)?[^():\s]+):(\d+):\d+\)?$", s)
            if m_loc:
                p = m_loc.group(1).replace("file://", "")
                if ctx.is_student_path(p):
                    frames.append(f"{p}:{m_loc.group(2)}")

    if diff_student:
        returned.append("\n".join(diff_student))
    elif actual_yaml:
        returned.append("\n".join(actual_yaml))

    if err_name == "AssertionError" or returned:
        return "AssertionError", returned, None, frames
    if err_name or err_first:
        raised = f"{err_name}: {err_first}" if err_name and err_first and not err_first.startswith(err_name) else (err_first or err_name)
        kind = f"raised {err_name}" if err_name else "error"
        return kind, [], raised, frames
    return "failed", [], None, frames


def _parse_bats_or_tap(lines: list[str], exit_code: int, timed_out: bool, ctx: _TaskContext) -> FeedbackReport | None:
    if not (any(_TAP_NOT_OK_RE.match(ln) for ln in lines) or any(_BATS_PRETTY_FAIL_RE.match(ln) for ln in lines)):
        return None

    report = FeedbackReport(exit_code=exit_code, timed_out=timed_out)
    pending_stdout: list[str] = []
    n = len(lines)
    i = 0

    while i < n:
        ln = lines[i]
        if re.match(r"^ok\s+\d+\b", ln) or re.match(r"^\s*\d+/\d+\s+✓\s+", ln):
            pending_stdout = []
            i += 1
            continue

        if ln.lstrip().startswith("#"):
            c_top = ln.lstrip()[1:].lstrip()
            if c_top.startswith("Subtest:"):
                i += 1
                continue
            if c_top and not _TAP_SUMMARY_COMMENT_RE.match(c_top) and not ctx.is_test_print_line(c_top):
                pending_stdout.append(c_top)
            i += 1
            continue

        m = _TAP_NOT_OK_RE.match(ln) or _BATS_PRETTY_FAIL_RE.match(ln)
        if m:
            name = ctx.clean_check_name(m.group(1))
            i += 1
            stdout: list[str] = list(pending_stdout)
            pending_stdout = []
            returned: list[str] = []
            raised: str | None = None
            frames: list[str] = []
            kind = "failed"
            while i < n:
                nxt = lines[i]
                if (
                    _TAP_NOT_OK_RE.match(nxt)
                    or _BATS_PRETTY_FAIL_RE.match(nxt)
                    or re.match(r"^ok\s+\d+\b", nxt)
                    or re.match(r"^\s*\d+/\d+\s+✓\s+", nxt)
                    or re.match(r"^1\.\.\d+$", nxt.strip())
                    or re.match(r"^\d+\s+tests?,\s+\d+\s+failures?", nxt.strip())
                ):
                    break
                if nxt == "  ---":
                    i += 1
                    yaml_lines: list[str] = []
                    while i < n and lines[i] != "  ...":
                        yaml_lines.append(lines[i])
                        i += 1
                    if i < n and lines[i] == "  ...":
                        i += 1
                    y_kind, y_ret, y_raised, y_frames = _parse_tap_yaml_block(yaml_lines, ctx)
                    kind = y_kind
                    returned.extend(y_ret)
                    if y_raised:
                        raised = y_raised
                    frames.extend(y_frames)
                    continue
                c = nxt.lstrip()
                if c.startswith("#"):
                    c = c[1:].lstrip()
                if _TAP_SUMMARY_COMMENT_RE.match(c):
                    i += 1
                    continue
                # Skip Bats lines that quote the private `.bats` test file or failed test command
                if c.startswith("(in test file ") or c.startswith("(from function ") or re.match(r"^`.*'\s+failed(?:\s+with status \d+)?$", c):
                    ctx.add_private_text(c)
                    i += 1
                    continue
                m_exp = re.match(r"^expected\s*:\s*(.+)$", c, re.IGNORECASE)
                m_act = re.match(r"^actual\s*:\s*(.+)$", c, re.IGNORECASE)
                if m_exp:
                    ctx.add_private_text(m_exp.group(1))
                elif m_act:
                    returned.append(m_act.group(1).strip())
                    kind = "assertion failed"
                elif c and not c.startswith("-- ") and not ctx.is_test_print_line(c):
                    stdout.append(c)
                i += 1
            report.checks.append(
                CheckFailure(
                    name=name,
                    kind=kind,
                    returned=returned,
                    raised=raised,
                    frames=frames,
                    stdout=stdout,
                )
            )
            continue
        i += 1

    return report

